{"sql":"-- Fix Channel Moderators DELETE policy
DROP POLICY IF EXISTS delete_channel_moderators_owner_or_self ON public.channel_moderators;

CREATE POLICY delete_channel_moderators_owner_or_self ON public.channel_moderators
FOR DELETE
USING (is_channel_owner(channel_id, app_current_user_id()) OR user_id = app_current_user_id());"}
